// Alertmanager webhook payload, version 4:
// https://prometheus.io/docs/alerting/latest/configuration/#webhook_config
// Anything malformed is rejected here, so later nodes can trust every field they read.
const MAX_ALERTS = 50;
const MAX_TEXT = 200;
const body = $input.first().json.body;

const reject = (reason) => [{
  json: { valid: false, reason, payloadExcerpt: JSON.stringify(body ?? null).slice(0, 2000) },
}];
const label = (labels, key, fallback) => {
  const value = labels[key];
  if (value === undefined) return fallback;
  if (typeof value !== 'string' || value.trim() === '' || value.length > MAX_TEXT) return null;
  return value.trim();
};

if (body === null || typeof body !== 'object' || Array.isArray(body)) return reject('body must be a JSON object');
if (body.version !== '4') return reject('unsupported webhook payload version');
if (!Array.isArray(body.alerts) || body.alerts.length === 0) return reject('alerts must be a non-empty array');
if (body.alerts.length > MAX_ALERTS) return reject(`a delivery may carry at most ${MAX_ALERTS} alerts`);

const alerts = [];
for (const [i, alert] of body.alerts.entries()) {
  if (alert === null || typeof alert !== 'object') return reject(`alerts[${i}] must be an object`);
  const labels = alert.labels && typeof alert.labels === 'object' ? alert.labels : {};
  if (!['firing', 'resolved'].includes(alert.status)) return reject(`alerts[${i}].status must be firing or resolved`);

  const alertname = label(labels, 'alertname', null);
  if (!alertname) return reject(`alerts[${i}].labels.alertname is missing or invalid`);
  const service = label(labels, 'service', 'unknown');
  const namespace = label(labels, 'namespace', 'default');
  const severity = label(labels, 'severity', 'warning');
  if (!service || !namespace || !severity) return reject(`alerts[${i}] has an invalid service, namespace or severity label`);

  const startsAt = new Date(alert.startsAt);
  if (typeof alert.startsAt !== 'string' || Number.isNaN(startsAt.getTime())) {
    return reject(`alerts[${i}].startsAt is not a valid timestamp`);
  }

  alerts.push({
    alertname, service, namespace, severity,
    status: alert.status,
    summary: String(alert.annotations?.summary ?? '').slice(0, 500),
    startsAt: startsAt.toISOString(),
    // Same alert in the same firing episode -> same incident. A new episode has a new startsAt.
    identity: JSON.stringify([alertname, namespace, service, startsAt.toISOString()]),
  });
}

return [{
  json: {
    valid: true,
    receiver: String(body.receiver ?? '').slice(0, MAX_TEXT),
    groupKey: String(body.groupKey ?? '').slice(0, 1000),
    alerts,
    payload: body,
  },
}];

// One item per alert from here on. The delivery id links every later record back to the stored payload.
const batch = $('Validate and normalize').first().json;
const deliveryId = $('Record delivery').first().json.delivery_id;
return batch.alerts.map((alert) => ({ json: { ...alert, deliveryId } }));

// Services missing from the catalog still get an owner and a runbook, so no alert is dropped
// for lack of metadata; they page only on critical.
const DEFAULT_POLICY = { owner: 'platform-oncall', runbook: 'runbooks/unknown-service.md', page_severities: ['critical'] };

const alert = $('Fingerprint alert').item.json;
const inCatalog = typeof $json.owner === 'string';
const policy = inCatalog ? $json : DEFAULT_POLICY;
const pages = alert.status === 'firing' && policy.page_severities.includes(alert.severity);

return {
  json: {
    ...alert,
    owner: policy.owner,
    runbook: policy.runbook,
    enrichment: inCatalog ? 'catalog' : 'default',
    initialNotifyStatus: pages ? 'pending' : 'skipped',
  },
};
